package com.troday.api.service;
import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service public class ContractService {
 @org.springframework.beans.factory.annotation.Autowired private DomainSupport domain;
 @org.springframework.beans.factory.annotation.Value("${troday.contracts.paper-import-users:}") private String paperImportUsers;
 private final AccountService accounts; private final ContractRepository contracts; private final ContractRevisionRepository revisions; private final RoomTenantRepository members; private final RoomRepository rooms; private final RentalHouseRepository houses; private final ViewingRepository viewings;
 public ContractService(AccountService a,ContractRepository c,ContractRevisionRepository r,RoomTenantRepository m,RoomRepository rooms,RentalHouseRepository h,ViewingRepository v){accounts=a;contracts=c;revisions=r;members=m;this.rooms=rooms;houses=h;viewings=v;}
 public ApiResponseDto<?> list(HttpServletRequest r){
Long me=accounts.authenticatedUserId(r);return ok("GET",domain.page(r,"FROM contracts c WHERE (c.landlord_id=? OR EXISTS(SELECT 1 FROM room_tenants m WHERE m.contract_id=c.id AND m.tenant_id=?))","c.id","c.contract_number","c.id DESC",List.of(me,me),Map.of("status","c.status","roomId","c.room_id","houseId","c.house_id"),id->contractData(contracts.findById(id).orElseThrow())));
 }
 public ApiResponseDto<?> detail(HttpServletRequest r,Long id){return ok("GET",contractData(access(r,id)));}
 public ApiResponseDto<?> create(HttpServletRequest r,JsonNode b){
Long owner=accounts.authenticatedUserId(r); com.fasterxml.jackson.databind.node.ArrayNode extra=new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode();
        if(b.has("extraMembers")){if(!b.get("extraMembers").isArray())throw bad("extraMembers phải là danh sách");for(JsonNode member:b.get("extraMembers")){var n=extra.addObject();n.put("full_name",text(member,"fullName"));if(member.hasNonNull("tenantId"))n.put("tenant_id",requiredLong(member,"tenantId"));if(member.hasNonNull("identityNumber"))n.put("identity_number",text(member,"identityNumber"));if(member.hasNonNull("dateOfBirth"))n.put("date_of_birth",text(member,"dateOfBirth"));}}
        Long templateId = b.hasNonNull("templateId") ? requiredLong(b, "templateId") : null;
        if (templateId != null && !domain.exists("SELECT id FROM contract_templates WHERE id=? AND active=TRUE", templateId)) throw bad("Mẫu hợp đồng không còn khả dụng");
        Long id=domain.procedure("sp_create_rental_contract",true,requiredLong(b,"viewingId"),owner,text(b,"contractNumber"),date(b,"startDate"),date(b,"endDate"),decimal(b,"rentAmount",BigDecimal.ZERO),decimal(b,"depositAmount",BigDecimal.ZERO),text(b,"content"),templateId,extra.toString());
        return ok("POST",contractData(contracts.findById(id).orElseThrow()));
 }
 public ApiResponseDto<?> contractImpact(HttpServletRequest r,Long viewingId){
Long me=accounts.authenticatedUserId(r);Viewing v=viewings.findById(viewingId).orElseThrow(()->notFound("Không tìm thấy lịch xem"));if(!v.getCreatedById().equals(me))throw forbidden("Không có quyền");return ok("GET",Map.of("futureViewingsCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM room_viewing_requests WHERE room_id=? AND status='SCHEDULED'",Long.class,v.getRoomId()),"pendingProposalsCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM room_viewing_proposals WHERE room_id=? AND status='PENDING' AND starts_at>UTC_TIMESTAMP(6)",Long.class,v.getRoomId()),"expiredProposalsCount",domain.jdbc.queryForObject("SELECT COUNT(*) FROM room_viewing_proposals WHERE room_id=? AND status='PENDING' AND starts_at<=UTC_TIMESTAMP(6)",Long.class,v.getRoomId()),"asOf",LocalDateTime.now(ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS)));
 }
 public ApiResponseDto<?> revisionList(HttpServletRequest r,Long id){access(r,id);return ok("GET",revisions.findByContractIdOrderByRevisionNumberDesc(id).stream().map(this::revisionData).toList());}
 @Transactional public ApiResponseDto<?> revisionRequest(HttpServletRequest r,Long id,JsonNode b){
Long me=accounts.authenticatedUserId(r);domain.lockContract(id);Contract c=access(r,id);
        if(!domain.representative(id,me))throw forbidden("Chỉ đại diện hiện tại được yêu cầu sửa");if(!"PENDING_CONFIRMATION".equals(c.getStatus()))throw conflict("Hợp đồng không chờ xác nhận");
        ContractRevision old=currentRevision(c);if(b.hasNonNull("revisionId")&&!Objects.equals(requiredLong(b,"revisionId"),old.getId()))throw conflict("Revision đã thay đổi");
        old.setStatus("CANCELLED");revisions.saveAndFlush(old);ContractRevision n=new ContractRevision();copyRevision(old,n);n.setRevisionNumber(old.getRevisionNumber()+1);n.setStatus("DRAFT");n.setCreatedById(me);n.setTenantFeedback(text(b,"reason"));n=revisions.saveAndFlush(n);c.setCurrentRevisionId(n.getId());c.setStatus("DRAFT");contracts.saveAndFlush(c);return ok("POST",revisionData(n));
 }
 @Transactional public ApiResponseDto<?> patchRevision(HttpServletRequest r,Long cid,Long rid,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được sửa bản nháp");ContractRevision n=revisions.findById(rid).filter(x->x.getContractId().equals(cid)).orElseThrow(()->notFound("Không tìm thấy revision"));if(!"DRAFT".equals(n.getStatus()))throw conflict("Revision không còn là bản nháp");if(b.hasNonNull("startDate"))n.setStartDate(date(b,"startDate"));if(b.hasNonNull("endDate"))n.setEndDate(date(b,"endDate"));if(b.hasNonNull("rentAmount"))n.setRentAmount(decimal(b,"rentAmount",BigDecimal.ZERO));if(b.hasNonNull("depositAmount"))n.setDepositAmount(decimal(b,"depositAmount",BigDecimal.ZERO));if(b.hasNonNull("content"))n.setContent(text(b,"content"));return ok("PATCH",revisionData(revisions.save(n)));}
 @Transactional public ApiResponseDto<?> submitRevision(HttpServletRequest r,Long cid,Long rid){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được gửi revision");ContractRevision n=revisions.findById(rid).filter(x->x.getContractId().equals(cid)).orElseThrow(()->notFound("Không tìm thấy revision"));if(!"DRAFT".equals(n.getStatus()))throw conflict("Revision không còn là bản nháp");n.setStatus("PENDING_CONFIRMATION");n.setLandlordConfirmedById(owner);n.setLandlordConfirmedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));n.setSentAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));c.setCurrentRevisionId(n.getId());c.setStatus("PENDING_CONFIRMATION");revisions.saveAndFlush(n);contracts.saveAndFlush(c);return ok("POST",revisionData(n));}
 @Transactional public ApiResponseDto<?> confirm(HttpServletRequest r,Long id,JsonNode b){
Long me=accounts.authenticatedUserId(r);domain.lockContract(id);Contract c=access(r,id);if(!domain.representative(id,me))throw forbidden("Chỉ đại diện hiện tại được xác nhận");
        if(!Objects.equals(requiredLong(b,"revisionId"),c.getCurrentRevisionId()))throw conflict("Revision đã thay đổi");ContractRevision n=currentRevision(c);if(!"PENDING_CONFIRMATION".equals(c.getStatus())||!"PENDING_CONFIRMATION".equals(n.getStatus()))throw conflict("Hợp đồng không chờ xác nhận");
        LocalDateTime now=LocalDateTime.now(ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS);n.setTenantConfirmedById(me);n.setTenantConfirmedAt(now);n.setStatus("CONFIRMED");n.setAppliedAt(now);revisions.saveAndFlush(n);c.setStatus("CONFIRMED");contracts.saveAndFlush(c);return ok("POST",contractData(c));
 }
 public ApiResponseDto<?> moveIn(HttpServletRequest r,Long id,JsonNode b){
access(r,id);if(b==null||!b.path("memberIds").isArray()||b.path("memberIds").isEmpty())throw bad("Cần chọn memberIds thực tế vào ở");
        com.fasterxml.jackson.databind.node.ArrayNode ids=new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode();for(JsonNode value:b.get("memberIds")){if(!value.asText().matches("[1-9][0-9]{0,18}"))throw bad("memberIds không hợp lệ");ids.add(value.asLong());}domain.procedure("sp_confirm_move_in",false,id,ids.toString(),date(b,"moveInDate"),accounts.authenticatedUserId(r));return ok("POST",contractData(contracts.findById(id).orElseThrow()));
 }
 public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){
access(r,id);if(text(b,"reason").isBlank())throw bad("Cần lý do hủy hợp đồng");domain.procedure("sp_cancel_contract",false,id,accounts.authenticatedUserId(r),text(b,"reason"));return ok("POST",contractData(contracts.findById(id).orElseThrow()));
 }
 public ApiResponseDto<?> cancelMember(HttpServletRequest r,Long cid,Long mid,JsonNode b){
access(r,cid);domain.procedure("sp_cancel_planned_member",false,cid,mid,accounts.authenticatedUserId(r),text(b,"reason"));return ok("POST",memberData(members.findById(mid).orElseThrow()));
 }
 @Transactional public ApiResponseDto<?> importPaper(HttpServletRequest r,JsonNode b){
Long owner=accounts.authenticatedUserId(r);if(Arrays.stream(paperImportUsers.split(",")).map(String::trim).noneMatch(value->value.equals(String.valueOf(owner))))throw forbidden("Tài khoản chưa được cấp quyền nhập hợp đồng giấy");Long rid=requiredLong(b,"roomId"),file=requiredLong(b,"paperDocumentFileId");domain.activeFile(file,owner,"CONTRACT");domain.jdbc.queryForList("SELECT id FROM rooms WHERE id=? FOR UPDATE",rid);Room room=rooms.findById(rid).orElseThrow(()->notFound("Không tìm thấy phòng"));RentalHouse h=houses.findById(room.getHouseId()).orElseThrow();if(!owner.equals(h.getLandlordId()))throw forbidden("Không sở hữu phòng");
        if(!b.path("members").isArray()||b.path("members").isEmpty())throw bad("Cần danh sách thành viên và đại diện của hợp đồng giấy");if(text(b,"content").isBlank())throw bad("Cần snapshot nội dung đã ký");
        Contract c=new Contract();c.setContractNumber(text(b,"contractNumber"));c.setRoomId(rid);c.setHouseId(h.getId());c.setLandlordId(owner);c.setSource("PAPER_IMPORT");c.setPaperDocumentFileId(file);c.setStartDate(date(b,"startDate"));c.setEndDate(date(b,"endDate"));c.setRentAmount(decimal(b,"rentAmount",BigDecimal.ZERO));c.setDepositAmount(decimal(b,"depositAmount",BigDecimal.ZERO));c.setStatus("DRAFT");c=contracts.saveAndFlush(c);
        List<RoomTenant> imported=new ArrayList<>();List<Map<String,Object>> snapshots=new ArrayList<>();Long representative=null;Map<Long,LocalDate> arrivals=new LinkedHashMap<>();
        for(JsonNode n:b.path("members")){RoomTenant m=new RoomTenant();m.setContractId(c.getId());m.setRoomId(rid);m.setFullName(text(n,"fullName"));m.setTenantId(n.hasNonNull("tenantId")?requiredLong(n,"tenantId"):null);m.setStatus("PLANNED");m.setIntakeSource("PAPER_IMPORT");m.setPlannedMoveInDate(n.hasNonNull("moveInDate")?date(n,"moveInDate"):c.getStartDate());if(m.getFullName().isBlank())throw bad("Thành viên cần họ tên");m=members.saveAndFlush(m);imported.add(m);snapshots.add(memberData(m));if(n.path("representative").asBoolean()){if(representative!=null||m.getTenantId()==null)throw bad("Cần đúng một đại diện có tài khoản");representative=m.getId();}if(n.hasNonNull("moveInDate"))arrivals.put(m.getId(),date(n,"moveInDate"));}
        if(representative==null)throw bad("Cần chọn đại diện");ContractRevision rev=newRevision(c,b,representative,1);rev.setKind("PAPER_IMPORT");rev.setStatus("IMPORTED");rev.setDocumentFileId(file);rev.setMembersSnapshot(domain.json(snapshots));rev=revisions.saveAndFlush(rev);domain.jdbc.update("UPDATE contract_revisions SET document_file_id=? WHERE id=?",file,rev.getId());
        c.setRepresentativeRoomTenantId(representative);c.setCurrentRevisionId(rev.getId());c.setStatus("CONFIRMED");contracts.saveAndFlush(c);
        if(!arrivals.isEmpty()){if(!arrivals.containsKey(representative))throw bad("Đại diện phải vào ở trước khi nhập người đã đến");for(var arrival:arrivals.entrySet())domain.jdbc.update("UPDATE room_tenants SET status='ACTIVE',move_in_date=?,move_in_confirmed_by_id=?,move_in_confirmed_at=UTC_TIMESTAMP(6) WHERE id=?",arrival.getValue(),owner,arrival.getKey());domain.jdbc.update("UPDATE contracts SET status='ACTIVE',activated_at=UTC_TIMESTAMP(6) WHERE id=?",c.getId());}
        domain.jdbc.update("UPDATE rooms SET status=? WHERE id=?",arrivals.isEmpty()?"RESERVED":"OCCUPIED",rid);return ok("POST",Map.of("contractId",c.getId(),"id",c.getId(),"source","PAPER_IMPORT","warnings",List.of()));
 }
 private Contract access(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Contract c=contracts.findById(id).orElseThrow(()->notFound("Không tìm thấy hợp đồng"));if(!domain.contractReader(id,me))throw forbidden("Không có quyền với hợp đồng");return c;}
 private ContractRevision currentRevision(Contract c){if(c.getCurrentRevisionId()==null)throw conflict("Hợp đồng chưa có revision");return revisions.findById(c.getCurrentRevisionId()).orElseThrow(()->notFound("Không tìm thấy revision hiện hành"));}
 private ContractRevision newRevision(Contract c,JsonNode b,Long member, int number){ContractRevision n=new ContractRevision();n.setContractId(c.getId());n.setRevisionNumber(number);n.setCreatedById(c.getLandlordId());n.setKind("INITIAL");n.setStartDate(c.getStartDate());n.setEndDate(c.getEndDate());n.setEffectiveFrom(c.getStartDate());n.setRentAmount(c.getRentAmount());n.setDepositAmount(c.getDepositAmount());n.setContent(text(b,"content"));n.setMembersSnapshot("[{\"roomTenantId\":"+member+"}]");n.setRepresentativeRoomTenantId(member);return n;}
 private void copyRevision(ContractRevision o,ContractRevision n){n.setContractId(o.getContractId());n.setCreatedById(o.getCreatedById());n.setKind(o.getKind());n.setStartDate(o.getStartDate());n.setEndDate(o.getEndDate());n.setEffectiveFrom(o.getEffectiveFrom());n.setRentAmount(o.getRentAmount());n.setDepositAmount(o.getDepositAmount());n.setContent(o.getContent());n.setMembersSnapshot(o.getMembersSnapshot());n.setRepresentativeRoomTenantId(o.getRepresentativeRoomTenantId());n.setTemplateId(o.getTemplateId());}
 private Map<String,Object> contractData(Contract c){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("contractNumber",c.getContractNumber());m.put("roomId",c.getRoomId());m.put("houseId",c.getHouseId());m.put("landlordId",c.getLandlordId());m.put("viewingId",c.getViewingId());m.put("viewingTenantId",c.getViewingTenantId());m.put("status",c.getStatus());m.put("source",c.getSource());m.put("activatedAt",domain.jdbc.queryForObject("SELECT activated_at FROM contracts WHERE id=?",LocalDateTime.class,c.getId()));m.put("closedAt",domain.jdbc.queryForObject("SELECT closed_at FROM contracts WHERE id=?",LocalDateTime.class,c.getId()));m.put("startDate",c.getStartDate());m.put("endDate",c.getEndDate());m.put("rentAmount",c.getRentAmount());m.put("depositAmount",c.getDepositAmount());m.put("currentRevisionId",c.getCurrentRevisionId());m.put("representativeRoomTenantId",c.getRepresentativeRoomTenantId());m.put("representativeTenantId",members.findById(c.getRepresentativeRoomTenantId()==null?-1L:c.getRepresentativeRoomTenantId()).map(RoomTenant::getTenantId).orElse(null));m.put("members",members.findAll().stream().filter(x->c.getId().equals(x.getContractId())).map(this::memberData).toList());return m;}
 private Map<String,Object> revisionData(ContractRevision n){Map<String,Object> m=new LinkedHashMap<>();m.put("id",n.getId());m.put("contractId",n.getContractId());m.put("revisionNumber",n.getRevisionNumber());m.put("kind",n.getKind());m.put("status",n.getStatus());m.put("startDate",n.getStartDate());m.put("endDate",n.getEndDate());m.put("rentAmount",n.getRentAmount());m.put("depositAmount",n.getDepositAmount());m.put("content",n.getContent());m.put("tenantConfirmedAt",n.getTenantConfirmedAt());m.put("tenantFeedback",n.getTenantFeedback());m.put("membersSnapshot",n.getMembersSnapshot());m.put("templateId",n.getTemplateId());if(n.getTemplateId()!=null)m.putAll(domain.jdbc.queryForMap("SELECT name AS templateName,version AS templateVersion FROM contract_templates WHERE id=?",n.getTemplateId()));m.put("documentFileId",n.getDocumentFileId());m.put("effectiveFrom",n.getEffectiveFrom());m.put("appliedAt",n.getAppliedAt());return m;}
 private Map<String,Object> memberData(RoomTenant m){Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.getId());x.put("contractId",m.getContractId());x.put("roomId",m.getRoomId());x.put("tenantId",m.getTenantId());x.put("fullName",m.getFullName());x.put("status",m.getStatus());x.put("plannedMoveInDate",m.getPlannedMoveInDate());x.put("moveInDate",m.getMoveInDate());return x;}
 private LocalDate date(JsonNode b,String k){try{return LocalDate.parse(text(b,k));}catch(Exception e){throw bad(k+" không hợp lệ");}}private BigDecimal decimal(JsonNode b,String k,BigDecimal d){if(!b.hasNonNull(k))return d;try{return new BigDecimal(b.get(k).asText());}catch(Exception e){throw bad(k+" không hợp lệ");}}private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();}private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
